#!/usr/bin/env node

import { execSync } from 'child_process';
import { resolve } from 'path';

const PROJECT_ROOT = resolve(import.meta.dirname, '..', '..');

function usage(): never {
  console.log(`
deepenc-harness - Build and test the deepenc encoder library

Usage:
  deepenc-harness build [options]
  deepenc-harness test  [options]
  deepenc-harness build --test [options]

Options:
  -v, --variant <type>   Build variant: release, debug, relwithdebinfo (default: release)
  -s, --static           Build/test static libraries (default: shared)
  -c, --clean            Clean before building
  -j, --jobs <N>         Number of parallel jobs
  -t, --test             Run tests after building
  --help                 Show this message
`);
  process.exit(0);
}

function parseArgs() {
  const args = process.argv.slice(2);
  let command = '';
  const opts: Record<string, string | boolean | number> = {
    variant: 'release',
    static: false,
    clean: false,
    test: false,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === 'build' && !command) { command = 'build'; continue; }
    if (arg === 'test' && !command) { command = 'test'; continue; }
    if (arg === '--help' || arg === '-h') { usage(); }
    if (arg === '--variant' || arg === '-v') { opts.variant = args[++i]; continue; }
    if (arg === '--static' || arg === '-s') { opts.static = true; continue; }
    if (arg === '--clean' || arg === '-c') { opts.clean = true; continue; }
    if (arg === '--jobs' || arg === '-j') { opts.jobs = parseInt(args[++i], 10); continue; }
    if (arg === '--test' || arg === '-t') { opts.test = true; continue; }
    console.error(`Unknown argument: ${arg}`);
    usage();
  }

  if (!command) command = 'build';
  return { command, opts };
}

function variantDir(variant: string, isStatic: boolean): string {
  return `build/${variant}${isStatic ? '-static' : '-shared'}`;
}

function run(cmd: string, cwd?: string) {
  const opts: Record<string, unknown> = { stdio: 'inherit' as const };
  if (cwd) opts.cwd = cwd;
  execSync(cmd, opts);
}

function doBuild(opts: Record<string, unknown>) {
  const variant = opts.variant as string || 'release';
  const isStatic = !!opts.static;
  const suffix = isStatic ? '' : '-shared';
  const target = `install-${variant}${suffix}`;

  const makeOpts: string[] = [];
  if (opts.jobs) makeOpts.push(`j=${opts.jobs}`);

  if (opts.clean) {
    run(`make clean-${variant}${suffix} ${makeOpts.join(' ')}`, PROJECT_ROOT);
  }

  const cmd = `make ${target} ${makeOpts.join(' ')}`;
  console.log(`\n  => ${cmd}\n`);
  run(cmd, PROJECT_ROOT);
}

function doTest(opts: Record<string, unknown>) {
  const variant = opts.variant as string || 'release';
  const isStatic = !!opts.static;
  const dir = variantDir(variant, isStatic);

  run(`ctest --test-dir ${dir} --output-on-failure`, PROJECT_ROOT);
}

const { command, opts } = parseArgs();

if (command === 'build') {
  doBuild(opts);
  if (opts.test) doTest(opts);
} else if (command === 'test') {
  doTest(opts);
}

